from typing import Mapping

def convert_currency(cents: int, source: str, target: str, rates: Mapping[str, str]) -> int:
    for code in (source, target):
        if code not in rates:
            raise ValueError(f"no exchange rate for {code}")
    source_rate = Decimal(rates[source])
    target_rate = Decimal(rates[target])
    if source_rate <= 0 or target_rate <= 0:
        raise ValueError("exchange rates must be positive")
    if source == target:
        return cents

    # Exact decimal calculation
    # value = cents * (target_rate / source_rate)
    # To avoid precision loss, multiply first then divide
    result = (Decimal(cents) * target_rate) / source_rate

    # Round to nearest integer using half_even
    return int(result.quantize(Decimal('1'), rounding=ROUND_HALF_EVEN))"}}}
